int findNthDigit(int p, int q, int n) {
    // Convert the fraction to a decimal string
    stringstream ss;
    ss << fixed << setprecision(18) << (double)p / q;
    string decimalStr = ss.str();

    // Erase "0." from the beginning of the string
    if(decimalStr.size() > 2 && decimalStr[0] == '0' && decimalStr[1] == '.') {
        decimalStr.erase(0, 2);
    }

    // Return the nth digit in the decimal part
    if(n <= decimalStr.size()) {
        return decimalStr[n - 1] - '0';
    }
    return -1; // Return -1 if n is out of bounds
}

