    bool swapped = true;  
    while (gap > 1 || swapped) {  
        gap = max(1, (gap * 10) / 13);  
        swapped = false;  
        for (int i = 0; i + gap < n; i++) {  
            if (nums[i] > nums[i + gap]) {  
