int eulerianNum(int n, int m) {
    vector<vector<long long>> dp(n + 1, vector<long long>(m + 1, 0));
    for (int i = 0; i <= n; ++i) dp[i][0] = 1;
    for (int j = 0; j <= m; ++j) dp[0][j] = 0;

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            dp[i][j] = (i - 1) * dp[i - 1][j] + (j) * dp[i - 1][j - 1];
        }
    }

    return dp[n][m];
}

