    int totalSum = 0;

    for (int i = 2; i <= limit; i++) {
        if (visited.count(i)) continue;
        int sumDiv = sumOfDivisors(i);
        if (sumDiv != i && sumOfDivisors(sumDiv) == i) {
            totalSum += i + sumDiv;
