    int magicSum = 0;
    for (int j = 0; j < n; j++) {
        magicSum += myMatrix[0][j];
    }

    for (int i = 0; i < n; i++) {
        int rowSum = 0;
        for (int j = 0; j < n; j++) {
            rowSum += myMatrix[i][j];
        }
        if (rowSum != magicSum) return false;
    }

    for (int j = 0; j < n; j++) {
        int colSum = 0;
        for (int i = 0; i < n; i++) {
            colSum += myMatrix[i][j];
        }
        if (colSum != magicSum) return false;
    }

    int diag1Sum = 0, diag2Sum = 0;
    for (int i = 0; i < n; i++) {
        diag1Sum += myMatrix[i][i];
        diag2Sum += myMatrix[i][n - 1 - i];
    }

    if (diag1Sum != magicSum || diag2Sum != magicSum) return false;

    return true;
}

