        reverse(arr.begin(), arr.begin() + k + 1);
    };

    for (int curr_size = nums.size(); curr_size > 1; --curr_size) {
        int max_idx = max_element(nums.begin(), nums.begin() + curr_size) - nums.begin();
        if (max_idx != curr_size - 1) {
