int minOps(vector<int> arr, int n, int k) {
    if (n <= 0 || k <= 1) return -1;

    int remainder = arr[0] % k;
    for (int i = 1; i < n; ++i) {
        if (arr[i] % k != remainder) {
            return -1;
        }
    }

    int median;
    vector<int> modArr = arr;
    for (int i = 0; i < n; ++i) {
        modArr[i] = (arr[i] - remainder) / k;
    }

    sort(modArr.begin(), modArr.end());
    if (n % 2 == 0) {
        median = modArr[n / 2 - 1];
    } else {
        median = modArr[n / 2];
    }

    int ops = 0;
    for (int i = 0; i < n; ++i) {
        ops += abs(modArr[i] - median);
    }

    return ops;
}

