int maxSum(vector<int> arr, int n) {
    vector<int> inc(n, 0);
    vector<int> dec(n, 0);

    inc[0] = arr[0];
    for (int i = 1; i < n; i++) {
        inc[i] = arr[i];
        for (int j = 0; j < i; j++) {
            if (arr[i] > arr[j] && inc[i] < inc[j] + arr[i]) {
                inc[i] = inc[j] + arr[i];
            }
        }
    }

    dec[n-1] = arr[n-1];
    for (int i = n-2; i >= 0; i--) {
        dec[i] = arr[i];
        for (int j = n-1; j > i; j--) {
            if (arr[i] > arr[j] && dec[i] < dec[j] + arr[i]) {
                dec[i] = dec[j] + arr[i];
            }
        }
    }

    int maxSum = 0;
    for (int i = 0; i < n; i++) {
        maxSum = max(maxSum, inc[i] + dec[i] - arr[i]);
    }

    return maxSum;
}

