int maxSubArraySumRepeated(vector<int> a, int n, int k) {
    int maxSum = INT_MIN, currentSum = 0;

    // Calculate max sum in single array using Kadane's Algorithm
    for (int i = 0; i < n; i++) {
        currentSum = max(a[i], currentSum + a[i]);
        maxSum = max(maxSum, currentSum);
    }

    // If k = 1, return the result for single array
    if (k == 1) return maxSum;

    // Calculate prefix sum and suffix sum
    int prefixSum = 0, maxPrefixSum = INT_MIN;
    for (int i = 0; i < n; i++) {
        prefixSum += a[i];
        maxPrefixSum = max(maxPrefixSum, prefixSum);
    }

    int suffixSum = 0, maxSuffixSum = INT_MIN;
    for (int i = n - 1; i >= 0; i--) {
        suffixSum += a[i];
        maxSuffixSum = max(maxSuffixSum, suffixSum);
    }

    // Calculate total sum of array
    int totalSum = accumulate(a.begin(), a.end(), 0);

    if (totalSum > 0) {
        return max(maxSum, maxPrefixSum + maxSuffixSum + (k - 2) * totalSum);
    } else {
        return max(maxSum, maxPrefixSum + maxSuffixSum);
    }
}

