    for (int i = 1; i <= n; i++) {
        for (int sum = 0; sum <= n * 9; sum++) {
            dp[i][sum] = 0;
            for (int digit = 0; digit <= 1; digit++) {
                if (sum >= digit)
                    dp[i][sum] += dp[i - 1][sum - digit];
            }
        }
    }

    double result = 0;
    for (int sum = 0; sum <= n * 9; sum++) {
        result += dp[n][sum] * dp[n][sum];
    }
    return result;
}

