vector<int> findMinimumRange(vector<vector<int>> list) {
    typedef pair<int, pair<int, int>> pii;
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    int minRange = INT_MAX, minElement, maxElement = INT_MIN;
    for (int i = 0; i < list.size(); i++) {
        pq.push({list[i][0], {i, 0}});
        maxElement = max(maxElement, list[i][0]);
    }
    minElement = pq.top().first;
    vector<int> result = {minElement, maxElement};
    while (true) {
        pii curr = pq.top(); pq.pop();
        int num = curr.first, listIndex = curr.second.first, elementIndex = curr.second.second;
        if (maxElement - num < minRange) {
            minRange = maxElement - num;
            result = {num, maxElement};
        }
        if (elementIndex + 1 < list[listIndex].size()) {
            pq.push({list[listIndex][elementIndex + 1], {listIndex, elementIndex + 1}});
            maxElement = max(maxElement, list[listIndex][elementIndex + 1]);
        } else {
            break;
        }
    }
    return result;
}

