int findWays(int m) {
    vector<int> values = {1, -1}; // Available values to use in sequences
    int n = values.size();
    int dp[m + 1][m + 1];
    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;

    for (int i = 1; i <= m; i++) {
        for (int j = 0; j <= i; j++) {
            for (int k = 0; k < n; k++) {
                int prev_sum = j - values[k];
                if (prev_sum >= 0 && prev_sum <= i - 1) {
                    dp[i][j] += dp[i - 1][prev_sum];
                }
            }
        }
    }

    int total_ways = 0;
    for (int x = 0; x <= m; x++) {
        total_ways += dp[m][x];
    }

    return total_ways;
}

