int ncrModp(int n, int r, int p) {
    if (r > n) return 0;
    if (r == 0 || r == n) return 1;

    vector<int> fact(n+1, 1);
    for (int i = 2; i <= n; i++) {
        fact[i] = (fact[i-1] * i) % p;
    }

    auto power = [](int x, int y, int p) -> int {
        int res = 1;
        x = x % p;
        while (y > 0) {
            if (y & 1) {
                res = (res * x) % p;
            }
            y = y >> 1;
            x = (x * x) % p;
        }
        return res;
    };

    int nCr = (fact[n] * power(fact[r], p-2, p) % p) * power(fact[n-r], p-2, p) % p;
    return nCr;
}

