int getMaxgold(vector<vector<int>> gold, int m, int n) {
    vector<vector<int>> dp(m, vector<int>(n, 0));

    for (int col = n - 1; col >= 0; col--) {
        for (int row = 0; row < m; row++) {
            int right = (col == n - 1) ? 0 : dp[row][col + 1];
            int rightUp = (row == 0 || col == n - 1) ? 0 : dp[row - 1][col + 1];
            int rightDown = (row == m - 1 || col == n - 1) ? 0 : dp[row + 1][col + 1];

            dp[row][col] = gold[row][col] + max({right, rightUp, rightDown});
        }
    }

    int maxGold = 0;
    for (int row = 0; row < m; row++) {
        maxGold = max(maxGold, dp[row][0]);
    }

    return maxGold;
}

