int findMax(vector<int> arr, int low, int high) {
    if (low == high) 
        return arr[low];
    if (high == low + 1)
        return max(arr[low], arr[high]);
    int mid = low + (high - low) / 2;
    if (arr[mid] > arr[mid + 1] && arr[mid] > arr[mid - 1])
        return arr[mid];
    if (arr[mid] > arr[high])
        return findMax(arr, mid + 1, high);
    return findMax(arr, low, mid - 1);
}

