int findKth(vector<int> arr1, vector<int> arr2, int m, int n, int k) {
    if (m > n) return findKth(arr2, arr1, n, m, k);
    if (m == 0) return arr2[k - 1];
    if (k == 1) return min(arr1[0], arr2[0]);

    int i = min(m, k / 2);
    int j = min(n, k / 2);

    if (arr1[i - 1] > arr2[j - 1]) 
        return findKth(arr1, vector<int>(arr2.begin() + j, arr2.end()), m, n - j, k - j);
    else 
        return findKth(vector<int>(arr1.begin() + i, arr1.end()), arr2, m - i, n, k - i);
}

