vector<int> getLudic(int n) {
    vector<int> ludicNumbers;
    vector<int> numbers(n);
    iota(numbers.begin(), numbers.end(), 1);

    int index = 1; // Start at the second element, since 1 is always ludic
    while (index < numbers.size()) {
        int step = numbers[index];
        ludicNumbers.push_back(step);
        numbers.erase(remove_if(numbers.begin() + index, numbers.end(),
                                [step](int val, int i = 0) mutable { return (++i) % step == 0; }),
                      numbers.end());
        ++index;
    }

    return ludicNumbers;
}

