int maxSumOfThreeConsecutive(vector<int> arr, int n) {
    if (n == 0) return 0;
    if (n == 1) return arr[0];
    if (n == 2) return arr[0] + arr[1];

    vector<int> dp(n, 0);
    dp[0] = arr[0];
    dp[1] = arr[0] + arr[1];
    dp[2] = max(arr[0] + arr[1], max(arr[1] + arr[2], arr[0] + arr[2]));

    for (int i = 3; i < n; ++i) {
        dp[i] = max({dp[i - 1], dp[i - 2] + arr[i], dp[i - 3] + arr[i] + arr[i - 1]});
    }

    return dp[n - 1];
}

