double maxaverageofpath(vector<vector<int>> cost, int n) {
    vector<vector<double>> dp(n, vector<double>(n, -1));

    function<double(int, int)> dfs = [&](int i, int j) -> double {
        if (i == n - 1 && j == n - 1) return cost[i][j];
        if (dp[i][j] != -1) return dp[i][j];

        double maxPath = -1;
        if (i + 1 < n) maxPath = max(maxPath, dfs(i + 1, j));
        if (j + 1 < n) maxPath = max(maxPath, dfs(i, j + 1));

        return dp[i][j] = cost[i][j] + maxPath;
    };

    double totalPathSum = dfs(0, 0);
    int totalSteps = (2 * n - 1);

    return totalPathSum / totalSteps;
}

