int nthSuperUglyNumber(int n, vector<int> primes) {
    priority_queue<long, vector<long>, greater<long>> minHeap;
    unordered_set<long> seen;

    minHeap.push(1);
    seen.insert(1);

    long current = 1;
    for (int i = 0; i < n; ++i) {
        current = minHeap.top();
        minHeap.pop();

        for (const int& prime : primes) {
            long next = current * prime;
            if (seen.find(next) == seen.end()) {
                seen.insert(next);
                minHeap.push(next);
            }
        }
    }
    return current;
}

