int coinChange(vector<int> s, int m, int n) {
    vector<int> dp(n + 1, 0);
    dp[0] = 1;

    for (int i = 0; i < m; i++) {
        for (int j = s[i]; j <= n; j++) {
            dp[j] += dp[j - s[i]];
        }
    }

    return dp[n];
}

