int rencontresNumber(int n, int m) {
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    dp[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        dp[i][0] = dp[i - 1][0] * (i - 1);
        for (int j = 1; j <= min(i, m); ++j) {
            dp[i][j] = (i - 1) * dp[i - 1][j] + dp[i - 1][j - 1];
        }
    }
    return dp[n][m];
}

