vector<int> findCloset(vector<int> a, vector<int> b, vector<int> c, int p, int q, int r) {
    int i = 0, j = 0, k = 0;
    int diff = INT_MAX;
    vector<int> result(3);
    while (i < p && j < q && k < r) {
        int minimum = min({a[i], b[j], c[k]});
        int maximum = max({a[i], b[j], c[k]});
        if (maximum - minimum < diff) {
            diff = maximum - minimum;
            result[0] = a[i];
            result[1] = b[j];
            result[2] = c[k];
        }
        if (a[i] == minimum) i++;
        else if (b[j] == minimum) j++;
        else k++;
    }
    return result;
}

