string sortList(vector<vector<int>> testList) {
    auto countDigits = [](const vector<int> &vec) {
        int digits = 0;
        for (int num : vec) {
            digits += to_string(num).length();
        }
        return digits;
    };

    sort(testList.begin(), testList.end(), [&](const vector<int>& a, const vector<int>& b) {
        return countDigits(a) < countDigits(b);
    });

    string result = "[";
    for (size_t i = 0; i < testList.size(); ++i) {
        result += "(";
        for (size_t j = 0; j < testList[i].size(); ++j) {
            result += to_string(testList[i][j]);
            if (j != testList[i].size() - 1) {
                result += ", ";
            }
        }
        if (testList[i].size() == 1) {
            result += ",";
        }
        result += ")";
        if (i != testList.size() - 1) {
            result += ", ";
        }
    }
    result += "]";

    return result;
}

