int ncrModP(int n, int r, int p) {
    if (r > n) return 0;
    if (r == 0 || r == n) return 1;

    vector<int> fact(n + 1, 1);
    for (int i = 2; i <= n; ++i) 
        fact[i] = fact[i-1] * i % p;

    auto modInverse = [](int a, int p) {
        int result = 1;
        int exp = p - 2;
        while (exp) {
            if (exp & 1) result = result * a % p;
            a = a * a % p;
            exp >>= 1;
        }
        return result;
    };

    int denominator = (fact[r] * fact[n - r]) % p;
    int denominatorInverse = modInverse(denominator, p);
    return (fact[n] * denominatorInverse) % p;
}

