int floorMax(int a, int b, int n) {
    int max_value = 0;
    for(int x = 0; x <= n; x++) {
        int current_value = floor((a * x) / b) - a * floor(x / b);
        max_value = max(max_value, current_value);
    }
    return max_value;
}

