int minSumPath(vector<vector<int>> a) {
    int n = a.size();
    for (int i = n - 2; i >= 0; i--) {
        for (int j = 0; j < a[i].size(); j++) {
            a[i][j] += min(a[i + 1][j], a[i + 1][j + 1]);
        }
    }
    return a[0][0];
}
